-- @seq 385
CREATE FUNCTION public.create_sales_order(p_tenant_id uuid, p_number text, p_customer_id text, p_issue_date date, p_expected_date date DEFAULT NULL::date, p_currency text DEFAULT 'USD'::text, p_items jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_so_id      uuid;
  v_item       jsonb;
  v_subtotal   numeric(18,4) := 0;
  v_tax_total  numeric(18,4) := 0;
  v_total      numeric(18,4) := 0;
  v_line_amt   numeric(18,4);
  v_tax_rate   numeric(6,4);
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'No sales order items provided';
  end if;

  insert into sales_orders (tenant_id, number, customer_id, issue_date, expected_date, currency, status, notes)
  values (p_tenant_id, p_number, p_customer_id, p_issue_date, p_expected_date, p_currency, 'draft', p_notes)
  returning id into v_so_id;

  for v_item in select jsonb_array_elements(p_items) loop
    v_line_amt := coalesce((v_item->>'quantity')::numeric, 1) * coalesce((v_item->>'unit_price')::numeric, 0)
                  - coalesce((v_item->>'discount')::numeric, 0);
    v_subtotal := v_subtotal + v_line_amt;

    v_tax_rate := 0;
    if v_item ? 'tax_id' and (v_item->>'tax_id') is not null then
      select rate into v_tax_rate from taxes where id = (v_item->>'tax_id')::uuid;
    end if;
    v_tax_total := v_tax_total + (v_line_amt * v_tax_rate);

    insert into sales_order_items (sales_order_id, product_id, inventory_item_id, account_id, tax_id,
                                   description, quantity, unit_price, discount, position)
    values (v_so_id,
            nullif(v_item->>'product_id','')::text,
            nullif(v_item->>'inventory_item_id','')::text,
            (v_item->>'account_id')::uuid,
            nullif(v_item->>'tax_id','')::uuid,
            v_item->>'description',
            coalesce((v_item->>'quantity')::numeric, 1),
            coalesce((v_item->>'unit_price')::numeric, 0),
            coalesce((v_item->>'discount')::numeric, 0),
            coalesce((v_item->>'position')::int, 0));
  end loop;

  v_total := v_subtotal + v_tax_total;
  update sales_orders set subtotal = v_subtotal, tax_total = v_tax_total, total = v_total
   where id = v_so_id;

  return v_so_id;
end;
$$;

-- @seq 410
CREATE FUNCTION public.erp__order_status(p_order_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE;
BEGIN
  SELECT * INTO o FROM erp_orders WHERE id = p_order_id FOR UPDATE;
  IF o.status IS NOT DISTINCT FROM p_status THEN RETURN; END IF;
  UPDATE erp_orders SET status = p_status, updated_at = now() WHERE id = p_order_id;   -- accounting sync fires here
  INSERT INTO erp_order_status_history(tenant_id, order_id, from_status, to_status, reason, changed_by, changed_at)
  VALUES (o.tenant_id, o.id, o.status, p_status, p_reason, auth.uid(), now());
END $$;

-- @seq 413
CREATE FUNCTION public.erp_add_order_note(p_order_id uuid, p_body text, p_note_type text DEFAULT 'internal'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_t uuid; v uuid;
BEGIN
  SELECT tenant_id INTO v_t FROM erp_orders WHERE id = p_order_id;
  PERFORM acct_assert_access(v_t);
  IF p_body IS NULL OR btrim(p_body) = '' THEN RAISE EXCEPTION 'Note text is required'; END IF;
  INSERT INTO erp_order_notes(tenant_id, order_id, note_type, body, created_by) VALUES (v_t, p_order_id, coalesce(p_note_type,'internal'), p_body, auth.uid())
  RETURNING id INTO v;
  IF p_note_type = 'problem' THEN
    UPDATE erp_orders SET status = 'on_hold', updated_at = now() WHERE id = p_order_id AND lower(status) NOT IN ('shipped','delivered','completed','closed','cancelled');
  END IF;
  RETURN v;
END $$;

-- @seq 415
CREATE FUNCTION public.erp_cancel_order(p_order_id uuid, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; r record;
BEGIN
  SELECT * INTO o FROM erp_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  PERFORM acct_assert_access(o.tenant_id);
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to cancel an order'; END IF;
  IF lower(o.status) IN ('cancelled','closed','returned') THEN RAISE EXCEPTION 'Order is already %', o.status; END IF;
  IF lower(o.status) IN ('shipped','delivered','completed','partially_shipped') THEN
    RAISE EXCEPTION 'Order % has shipped; open a return (RMA) instead of cancelling', o.order_number;
  END IF;
  FOR r IN SELECT * FROM erp_inventory_reservations WHERE tenant_id = o.tenant_id AND source_order_id = o.id AND status IN ('pending','reserved') LOOP
    UPDATE erp_inventory_reservations SET status = 'released', released_at = now() WHERE id = r.id;
    PERFORM erp__move(o.tenant_id, 'reservation_release', r.sku_id, r.warehouse_id, r.location_id, -r.quantity, NULL, 'erp_orders', o.id, o.order_number, 'Order cancelled');
  END LOOP;
  UPDATE erp_order_lines SET status = 'cancelled', updated_at = now() WHERE order_id = o.id AND status NOT IN ('shipped','delivered','returned');
  UPDATE erp_fulfillment_orders SET status = 'cancelled', updated_at = now() WHERE order_id = o.id AND status NOT IN ('shipped','delivered','closed');
  PERFORM erp__order_status(o.id, 'cancelled', p_reason);
  INSERT INTO erp_order_notes(tenant_id, order_id, note_type, body, created_by) VALUES (o.tenant_id, o.id, 'cancellation', p_reason, auth.uid());
  RETURN 'cancelled';
END $$;

-- @seq 418
CREATE FUNCTION public.erp_mark_shipped(p_order_id uuid, p_carrier_id uuid DEFAULT NULL::uuid, p_tracking_number text DEFAULT NULL::text, p_tracking_url text DEFAULT NULL::text, p_shipped_at timestamp with time zone DEFAULT now(), p_lines jsonb DEFAULT NULL::jsonb, p_warehouse_id uuid DEFAULT NULL::uuid, p_label_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v_wh uuid; v_ful uuid; v_ship uuid; l record; v_qty numeric; v_open numeric; v_any boolean := false; v_sku uuid;
BEGIN
  SELECT * INTO o FROM erp_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  PERFORM acct_assert_access(o.tenant_id);
  IF lower(o.status) IN ('cancelled','closed','draft') THEN RAISE EXCEPTION 'Order % is % and cannot ship', o.order_number, o.status; END IF;
  IF p_carrier_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM erp_carriers c WHERE c.id = p_carrier_id AND c.tenant_id = o.tenant_id AND coalesce(c.is_active,true)) THEN
    RAISE EXCEPTION 'Carrier is not active for this company';
  END IF;
  v_wh := coalesce(p_warehouse_id, erp__default_warehouse(o.tenant_id));
  INSERT INTO erp_fulfillment_orders(tenant_id, fulfillment_number, order_id, warehouse_id, method, status, dispatched_at, completed_at, created_by)
  VALUES (o.tenant_id, erp_next_document_number(o.tenant_id, 'fulfillment'), o.id, v_wh, coalesce(o.fulfillment_method,'ship'), 'shipped', p_shipped_at, p_shipped_at, auth.uid())
  RETURNING id INTO v_ful;
  FOR l IN SELECT * FROM erp_order_lines WHERE order_id = o.id AND status NOT IN ('cancelled','returned') ORDER BY created_at LOOP
    v_open := l.quantity - coalesce(l.quantity_shipped, 0);
    v_qty := CASE WHEN p_lines IS NULL THEN v_open
                  ELSE coalesce((SELECT (x->>'quantity')::numeric FROM jsonb_array_elements(p_lines) x WHERE (x->>'order_line_id')::uuid = l.id), 0) END;
    CONTINUE WHEN v_qty <= 0;
    IF v_qty > v_open THEN RAISE EXCEPTION 'Line % has only % left to ship', coalesce(l.description, l.id::text), v_open; END IF;
    v_sku := erp__sku_for_variant(o.tenant_id, l.sku_id);
    IF v_sku IS NOT NULL THEN
      INSERT INTO erp_fulfillment_lines(tenant_id, fulfillment_id, order_line_id, sku_id, quantity, quantity_picked, quantity_packed, quantity_shipped)
      VALUES (o.tenant_id, v_ful, l.id, v_sku, v_qty, v_qty, v_qty, v_qty);
      IF v_wh IS NOT NULL THEN   -- no warehouse = supplier / print-on-demand fulfilled, nothing leaves our stock
        PERFORM erp__move(o.tenant_id, 'ship', v_sku, v_wh, erp__default_location(o.tenant_id, v_wh), -v_qty, NULL, 'erp_orders', o.id,
                          o.order_number, 'Shipped', jsonb_build_object('order_id', o.id, 'fulfillment_id', v_ful, 'order_line_id', l.id));
      END IF;
    END IF;
    UPDATE erp_order_lines SET quantity_shipped = coalesce(quantity_shipped,0) + v_qty,
           status = CASE WHEN coalesce(quantity_shipped,0) + v_qty >= quantity THEN 'shipped' ELSE status END, updated_at = now()
     WHERE id = l.id;
    v_any := true;
  END LOOP;
  IF NOT v_any THEN RAISE EXCEPTION 'Nothing left to ship on order %', o.order_number; END IF;
  INSERT INTO erp_shipments(tenant_id, shipment_number, fulfillment_id, carrier_id, status, tracking_number, tracking_url, label_url, shipped_at)
  VALUES (o.tenant_id, erp_next_document_number(o.tenant_id, 'shipment'), v_ful, p_carrier_id, 'shipped', p_tracking_number, p_tracking_url, p_label_url, p_shipped_at)
  RETURNING id INTO v_ship;
  INSERT INTO erp_tracking_events(tenant_id, shipment_id, event_code, event_status, event_at, raw_payload)
  VALUES (o.tenant_id, v_ship, 'shipped', 'shipped', p_shipped_at, jsonb_build_object('source','manual'));
  -- reservations for this order are consumed
  UPDATE erp_inventory_reservations SET status = 'fulfilled', released_at = now()
   WHERE tenant_id = o.tenant_id AND source_order_id = o.id AND status IN ('pending','reserved');
  IF v_wh IS NOT NULL THEN PERFORM set_config('app.erp_warehouse_id', v_wh::text, true); END IF;
  PERFORM erp__order_status(o.id, CASE WHEN EXISTS (SELECT 1 FROM erp_order_lines WHERE order_id = o.id AND status NOT IN ('cancelled','returned','shipped','delivered','closed'))
                                       THEN 'partially_shipped' ELSE 'shipped' END, 'Shipment ' || coalesce(p_tracking_number, v_ship::text));
  PERFORM set_config('app.erp_warehouse_id', '', true);
  RETURN v_ship;
END $$;

-- @seq 420
CREATE FUNCTION public.erp_next_document_number(p_tenant_id uuid, p_document_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE v_prefix text; v_next bigint; v_padding integer;
BEGIN
    INSERT INTO erp_document_sequences(tenant_id, document_type, prefix) VALUES (p_tenant_id, p_document_type, UPPER(LEFT(p_document_type, 3)) || '-') ON CONFLICT (tenant_id, document_type) DO NOTHING;
    SELECT prefix, next_number, padding INTO v_prefix, v_next, v_padding FROM erp_document_sequences WHERE tenant_id = p_tenant_id AND document_type = p_document_type FOR UPDATE;
    UPDATE erp_document_sequences SET next_number = next_number + 1, updated_at = now() WHERE tenant_id = p_tenant_id AND document_type = p_document_type;
    RETURN v_prefix || LPAD(v_next::text, v_padding, '0');
END; $$;

-- @seq 422
CREATE FUNCTION public.erp_orders_channel_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.sales_channel IN ('amazon','etsy','ebay','tiktok_shop','whatnot','walmart')
     AND NOT coalesce((NEW.metadata->>'seller_collects_tax')::boolean, false) THEN
    NEW.is_marketplace_facilitated := true;
    NEW.marketplace_name := coalesce(NEW.marketplace_name, NEW.sales_channel);
  END IF;
  RETURN NEW;
END $$;

-- @seq 427
CREATE FUNCTION public.erp_record_tracking_event(p_shipment_id uuid, p_event_code text, p_event_at timestamp with time zone DEFAULT now(), p_location text DEFAULT NULL::text, p_raw jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s erp_shipments%ROWTYPE; v uuid; v_code text := lower(p_event_code); v_order uuid;
BEGIN
  SELECT * INTO s FROM erp_shipments WHERE id = p_shipment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Shipment not found'; END IF;
  PERFORM acct_assert_access(s.tenant_id);
  IF v_code NOT IN ('label_created','shipped','in_transit','out_for_delivery','delivered','exception','returned_to_sender','lost') THEN
    RAISE EXCEPTION 'Unknown tracking event % (label_created, shipped, in_transit, out_for_delivery, delivered, exception, returned_to_sender, lost)', p_event_code;
  END IF;
  INSERT INTO erp_tracking_events(tenant_id, shipment_id, event_code, event_status, location_text, event_at, raw_payload)
  VALUES (s.tenant_id, s.id, v_code, v_code, p_location, p_event_at, coalesce(p_raw, jsonb_build_object('source','manual'))) RETURNING id INTO v;
  UPDATE erp_shipments SET status = v_code, delivered_at = CASE WHEN v_code = 'delivered' THEN p_event_at ELSE delivered_at END, updated_at = now()
   WHERE id = s.id;
  SELECT f.order_id INTO v_order FROM erp_fulfillment_orders f WHERE f.id = s.fulfillment_id;
  IF v_code = 'delivered' AND v_order IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM erp_shipments s2 JOIN erp_fulfillment_orders f2 ON f2.id = s2.fulfillment_id
                      WHERE f2.order_id = v_order AND s2.status <> 'delivered')
     AND NOT EXISTS (SELECT 1 FROM erp_orders o WHERE o.id = v_order AND o.status = 'partially_shipped') THEN
    UPDATE erp_fulfillment_orders SET status = 'delivered', updated_at = now() WHERE order_id = v_order;
    PERFORM erp__order_status(v_order, 'delivered', 'Carrier delivered');
  END IF;
  RETURN v;
END $$;

-- @seq 430
CREATE FUNCTION public.erp_set_carrier_active(p_carrier_id uuid, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_t uuid;
BEGIN
  SELECT tenant_id INTO v_t FROM erp_carriers WHERE id = p_carrier_id;
  IF v_t IS NULL THEN RAISE EXCEPTION 'Carrier not found'; END IF;
  PERFORM platform__assert_tenant_admin(v_t);
  UPDATE erp_carriers SET is_active = p_active WHERE id = p_carrier_id;
END $$;

-- @seq 434
CREATE FUNCTION public.erp_validate_order_line_quantities() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.quantity_reserved < NEW.quantity_allocated THEN RAISE EXCEPTION 'Allocated quantity cannot exceed reserved quantity'; END IF;
    IF NEW.quantity_allocated < NEW.quantity_picked THEN RAISE EXCEPTION 'Picked quantity cannot exceed allocated quantity'; END IF;
    IF NEW.quantity_picked < NEW.quantity_packed THEN RAISE EXCEPTION 'Packed quantity cannot exceed picked quantity'; END IF;
    IF NEW.quantity_packed < NEW.quantity_shipped THEN RAISE EXCEPTION 'Shipped quantity cannot exceed packed quantity'; END IF;
    RETURN NEW;
END; $$;

-- @seq 436
CREATE FUNCTION public.fulfillment_package_lines_quantity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  ordered_qty integer;
  packaged_qty integer;
BEGIN
  SELECT quantity INTO ordered_qty
    FROM public.commerce_order_items
   WHERE id = NEW.order_item_id
   FOR UPDATE;
  IF ordered_qty IS NULL THEN
    RAISE EXCEPTION 'fulfillment package line references unknown order item %', NEW.order_item_id;
  END IF;
  SELECT COALESCE(SUM(quantity), 0) INTO packaged_qty
    FROM public.fulfillment_package_lines
   WHERE order_item_id = NEW.order_item_id
     AND id IS DISTINCT FROM NEW.id;
  IF packaged_qty + NEW.quantity > ordered_qty THEN
    RAISE EXCEPTION 'packaged quantity % exceeds ordered quantity % for order item %',
      packaged_qty + NEW.quantity, ordered_qty, NEW.order_item_id;
  END IF;
  RETURN NEW;
END;
$$;

-- @seq 541
CREATE FUNCTION public.shipping_apply_tiers() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  mult numeric := coalesce((SELECT value::text::numeric FROM app_settings WHERE key = 'pricing.markup_multiplier'), 1.55);
  n integer;
BEGIN
  WITH calc AS (
    SELECT cp.id,
           shipping_cost_for_lb(sku_weight_lb(es.weight, es.weight_uom)) AS ship,
           ROUND(cp.cost_price * mult, 2) AS base
      FROM commerce_prices cp
      JOIN commerce_catalog_items ci ON ci.id = cp.catalog_item_id
      JOIN erp_product_skus es ON es.id = ci.sku_id
     WHERE cp.cost_price > 0
  )
  UPDATE commerce_prices cp
     SET shipping_cost = calc.ship,
         price = calc.base + calc.ship,
         compare_at_price = CASE WHEN cp.compare_at_price > calc.base + calc.ship THEN cp.compare_at_price ELSE NULL END
    FROM calc WHERE calc.id = cp.id;
  GET DIAGNOSTICS n = ROW_COUNT;

  UPDATE erp_product_skus es
     SET unit_price = cp.price
    FROM commerce_catalog_items ci
    JOIN commerce_prices cp ON cp.catalog_item_id = ci.id AND cp.cost_price > 0
   WHERE ci.sku_id = es.id;
  RETURN n;
END $$;

-- @seq 542
CREATE FUNCTION public.sku_weight_lb(w numeric, uom text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN w IS NULL OR w <= 0 THEN 0
    WHEN lower(coalesce(uom, '')) IN ('lb', 'lbs') THEN w
    WHEN lower(coalesce(uom, '')) = 'oz' THEN w / 16.0
    WHEN lower(coalesce(uom, '')) = 'kg' THEN w * 2.20462
    ELSE w / 453.592
  END
$$;

